#!/usr/bin/env python3import asyncioimport jsonimport sslimport loggingimport socketimport uuidimport osimport sysimport base64import timefrom datetime import datetime, timedeltafrom aiohttp import webimport aiohttp_corsfrom aiohttp import WSMsgType# 配置日志logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')logger = logging.getLogger(__name__)# 存储连接connected_clients = {}  # client_id -> websocketclient_info = {}  # client_id -> {name, fps, has_audio, is_streaming, last_active}connected_clients_count = 0# 语音消息存储（临时）voice_messages = {}  # message_id -> {sender_id, audio_data, timestamp, duration}# 文件路径HTML_FILE = "index.html"CSS_FILE = "style.css"JS_FILE = "app.js"CERT_FILE = "server.crt"KEY_FILE = "server.key"# 获取本机IP地址def get_local_ip():    try:        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)        s.settimeout(0)        s.connect(('8.8.8.8', 1))        ip = s.getsockname()[0]        s.close()        return ip    except Exception:        try:            hostname = socket.gethostname()            ip = socket.gethostbyname(hostname)            return ip        except:            return "127.0.0.1"def generate_ssl_certificate():    """生成自签名SSL证书"""    print("=" * 60)    print("🔐 生成自签名SSL证书")    print("=" * 60)    if os.path.exists(CERT_FILE) and os.path.exists(KEY_FILE):        print("✅ 证书已存在，跳过生成")        return True    try:        from cryptography import x509        from cryptography.x509.oid import NameOID        from cryptography.hazmat.primitives import hashes, serialization        from cryptography.hazmat.primitives.asymmetric import rsa        print("🔧 正在生成私钥...")        private_key = rsa.generate_private_key(            public_exponent=65537,            key_size=2048,        )        print("🔧 正在生成证书...")        subject = issuer = x509.Name([            x509.NameAttribute(NameOID.COUNTRY_NAME, "CN"),            x509.NameAttribute(NameOID.STATE_OR_PROVINCE_NAME, "Local"),            x509.NameAttribute(NameOID.LOCALITY_NAME, "Local"),            x509.NameAttribute(NameOID.ORGANIZATION_NAME, "Camera Server"),            x509.NameAttribute(NameOID.COMMON_NAME, "localhost"),        ])        cert = x509.CertificateBuilder().subject_name(            subject        ).issuer_name(            issuer        ).public_key(            private_key.public_key()        ).serial_number(            x509.random_serial_number()        ).not_valid_before(            datetime.utcnow()        ).not_valid_after(            datetime.utcnow() + timedelta(days=365)        ).add_extension(            x509.SubjectAlternativeName([                x509.DNSName("localhost"),                x509.DNSName("127.0.0.1"),            ]),            critical=False,        ).sign(private_key, hashes.SHA256())        # 保存私钥        with open(KEY_FILE, "wb") as f:            f.write(private_key.private_bytes(                encoding=serialization.Encoding.PEM,                format=serialization.PrivateFormat.TraditionalOpenSSL,                encryption_algorithm=serialization.NoEncryption(),            ))        # 保存证书        with open(CERT_FILE, "wb") as f:            f.write(cert.public_bytes(serialization.Encoding.PEM))        print("✅ 自签名证书已生成!")        return True    except ImportError as e:        print("❌ 缺少cryptography库，请安装: pip install cryptography")        return False    except Exception as e:        print(f"❌ 生成证书失败: {e}")        return Falsedef get_ssl_context():    """获取SSL上下文"""    ssl_context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)    if not os.path.exists(CERT_FILE) or not os.path.exists(KEY_FILE):        if not generate_ssl_certificate():            return None    try:        ssl_context.load_cert_chain(CERT_FILE, KEY_FILE)        return ssl_context    except Exception as e:        logger.error(f"❌ 加载SSL证书失败: {e}")        return Noneasync def index(request):    """返回主页"""    try:        with open(HTML_FILE, 'r', encoding='utf-8') as f:            content = f.read()        return web.Response(text=content, content_type='text/html')    except FileNotFoundError:        return web.Response(text="<h1>服务器启动成功！</h1><p>HTML文件不存在</p>", content_type='text/html', status=404)async def style_css(request):    """返回CSS文件"""    try:        with open(CSS_FILE, 'r', encoding='utf-8') as f:            return web.Response(text=f.read(), content_type='text/css')    except FileNotFoundError:        return web.Response(text="/* CSS文件不存在 */", content_type='text/css', status=404)async def app_js(request):    """返回JS文件"""    try:        with open(JS_FILE, 'r', encoding='utf-8') as f:            return web.Response(text=f.read(), content_type='text/javascript')    except FileNotFoundError:        return web.Response(text="// JS文件不存在", content_type='text/javascript', status=404)async def ws_handler(request):    """处理WebSocket连接"""    ws = web.WebSocketResponse()    await ws.prepare(request)    # 生成客户端ID    client_id = str(uuid.uuid4())[:8]    logger.info(f"🔌 新客户端连接: {client_id}")    # 存储客户端信息    connected_clients[client_id] = ws    client_info[client_id] = {        'name': f'设备{client_id}',        'fps': 60,        'has_audio': False,        'is_streaming': False,        'last_active': datetime.now(),        'connected_at': datetime.now()    }    # 更新连接计数    global connected_clients_count    connected_clients_count = len(connected_clients)    try:        # 发送欢迎消息        await ws.send_json({            'type': 'welcome',            'client_id': client_id,            'message': '连接成功',            'total_clients': connected_clients_count        })        # 广播新客户端加入        await broadcast_to_others(client_id, {            'type': 'client_connected',            'client_id': client_id,            'client_name': client_info[client_id]['name'],            'total_clients': connected_clients_count        })        # 发送当前在线的客户端列表        online_clients = []        for cid, info in client_info.items():            if cid != client_id and info['is_streaming']:                online_clients.append({                    'client_id': cid,                    'client_name': info['name'],                    'fps': info['fps'],                    'has_audio': info['has_audio']                })        if online_clients:            await ws.send_json({                'type': 'online_clients',                'clients': online_clients            })        async for msg in ws:            if msg.type == WSMsgType.TEXT:                try:                    data = json.loads(msg.data)                    client_info[client_id]['last_active'] = datetime.now()                    if data.get('type') == 'camera_stream':                        # 处理视频流                        if not data.get('frame'):                            continue                        # 限制帧大小                        if len(data.get('frame', '')) > 5 * 1024 * 1024:  # 5MB                            continue                        # 更新客户端信息                        if 'device_name' in data:                            client_info[client_id]['name'] = data['device_name']                        if 'fps' in data:                            client_info[client_id]['fps'] = data['fps']                        if 'has_audio' in data:                            client_info[client_id]['has_audio'] = data['has_audio']                        # 转发给其他客户端                        await broadcast_to_others(client_id, {                            'type': 'camera_frame',                            'sender_id': client_id,                            'client_name': client_info[client_id]['name'],                            'fps': client_info[client_id]['fps'],                            'has_audio': client_info[client_id]['has_audio'],                            'timestamp': datetime.now().isoformat(),                            'frame': data.get('frame')                        })                    elif data.get('type') == 'voice_message':                        # 处理语音消息                        message_id = str(uuid.uuid4())[:8]                        audio_data = data.get('audio_data')                        duration = data.get('duration', 0)                        if not audio_data or len(audio_data) > 2 * 1024 * 1024:  # 2MB限制                            continue                        # 存储语音消息                        voice_messages[message_id] = {                            'sender_id': client_id,                            'sender_name': client_info[client_id]['name'],                            'audio_data': audio_data,                            'duration': duration,                            'timestamp': datetime.now().isoformat(),                            'size': len(audio_data)                        }                        logger.info(f"🎤 收到语音消息: {client_id} ({duration}秒, {len(audio_data)}字节)")                        # 广播语音消息                        await broadcast_to_all({                            'type': 'voice_message',                            'message_id': message_id,                            'sender_id': client_id,                            'sender_name': client_info[client_id]['name'],                            'duration': duration,                            'timestamp': datetime.now().isoformat(),                            'audio_data': audio_data                        })                    elif data.get('type') == 'start_stream':                        # 客户端开始流                        client_info[client_id]['is_streaming'] = True                        client_info[client_id]['fps'] = data.get('fps', 60)                        client_info[client_id]['has_audio'] = data.get('has_audio', False)                        client_info[client_id]['name'] = data.get('device_name', f'设备{client_id}')                        logger.info(f"📡 客户端 {client_id} 开始流")                        # 广播新流开始                        await broadcast_to_others(client_id, {                            'type': 'stream_started',                            'sender_id': client_id,                            'client_name': client_info[client_id]['name'],                            'fps': client_info[client_id]['fps'],                            'has_audio': client_info[client_id]['has_audio']                        })                    elif data.get('type') == 'stop_stream':                        # 客户端停止流                        client_info[client_id]['is_streaming'] = False                        client_info[client_id]['has_audio'] = False                        logger.info(f"📡 客户端 {client_id} 停止流")                        # 通知其他客户端                        await broadcast_to_others(client_id, {                            'type': 'stream_stopped',                            'sender_id': client_id                        })                    elif data.get('type') == 'device_info':                        # 更新设备信息                        if 'device_name' in data:                            client_info[client_id]['name'] = data['device_name']                        if 'has_audio' in data:                            client_info[client_id]['has_audio'] = data['has_audio']                        # 广播设备信息更新                        await broadcast_to_others(client_id, {                            'type': 'device_info',                            'sender_id': client_id,                            'device_name': client_info[client_id]['name'],                            'has_audio': client_info[client_id]['has_audio']                        })                    elif data.get('type') == 'ping':                        # 心跳包                        await ws.send_json({                            'type': 'pong',                            'timestamp': data.get('timestamp')                        })                except json.JSONDecodeError as e:                    logger.error(f"❌ JSON解析错误: {e}")                except Exception as e:                    logger.error(f"❌ 处理消息错误: {e}")            elif msg.type == WSMsgType.ERROR:                logger.error(f"❌ WebSocket错误: {ws.exception()}")    except Exception as e:        logger.error(f"❌ WebSocket连接异常: {e}")    finally:        # 清理客户端        if client_id in connected_clients:            del connected_clients[client_id]        if client_id in client_info:            del client_info[client_id]        # 更新连接计数        connected_clients_count = len(connected_clients)        logger.info(f"🔌 客户端断开: {client_id}, 剩余连接: {connected_clients_count}")        # 通知其他客户端断开连接        await broadcast_to_others(client_id, {            'type': 'client_disconnected',            'client_id': client_id        })    return wsasync def broadcast_to_others(sender_id, message):    """向除发送者外的所有客户端广播消息"""    disconnected_clients = []    for client_id, client_ws in connected_clients.items():        if client_id != sender_id and not client_ws.closed:            try:                await client_ws.send_json(message)            except Exception as e:                logger.error(f"❌ 发送消息到客户端 {client_id} 失败: {e}")                disconnected_clients.append(client_id)    # 清理断开连接的客户端    for client_id in disconnected_clients:        if client_id in connected_clients:            del connected_clients[client_id]        if client_id in client_info:            del client_info[client_id]async def broadcast_to_all(message):    """向所有客户端广播消息"""    disconnected_clients = []    for client_id, client_ws in connected_clients.items():        if not client_ws.closed:            try:                await client_ws.send_json(message)            except Exception as e:                logger.error(f"❌ 发送消息到客户端 {client_id} 失败: {e}")                disconnected_clients.append(client_id)    # 清理断开连接的客户端    for client_id in disconnected_clients:        if client_id in connected_clients:            del connected_clients[client_id]        if client_id in client_info:            del client_info[client_id]async def send_system_stats():    """定时发送系统统计信息"""    while True:        await asyncio.sleep(5)        try:            # 计算统计信息            streaming_clients = [                info for info in client_info.values()                if info.get('is_streaming', False)            ]            avg_fps = 0            if streaming_clients:                total_fps = sum(info.get('fps', 60) for info in streaming_clients)                avg_fps = round(total_fps / len(streaming_clients), 1)            stats_data = {                'type': 'system_stats',                'timestamp': datetime.now().isoformat(),                'total_clients': connected_clients_count,                'streaming_clients': len(streaming_clients),                'avg_fps': avg_fps            }            # 广播给所有客户端            await broadcast_to_all(stats_data)        except Exception as e:            logger.error(f"❌ 发送系统统计信息失败: {e}")async def cleanup_clients():    """清理不活跃的客户端"""    while True:        await asyncio.sleep(30)        try:            now = datetime.now()            disconnected = []            for client_id, info in list(client_info.items()):                if now - info['last_active'] > timedelta(seconds=60):                    ws = connected_clients.get(client_id)                    if ws and not ws.closed:                        await ws.close()                    disconnected.append(client_id)            for client_id in disconnected:                if client_id in connected_clients:                    del connected_clients[client_id]                if client_id in client_info:                    del client_info[client_id]            if disconnected:                logger.info(f"🧹 清理不活跃客户端: {disconnected}")        except Exception as e:            logger.error(f"❌ 清理客户端失败: {e}")async def cleanup_voice_messages():    """清理过期的语音消息"""    while True:        await asyncio.sleep(300)  # 每5分钟清理一次        try:            now = datetime.now()            expired = []            for msg_id, msg in list(voice_messages.items()):                msg_time = datetime.fromisoformat(msg['timestamp'])                if now - msg_time > timedelta(minutes=10):  # 10分钟过期                    expired.append(msg_id)            for msg_id in expired:                del voice_messages[msg_id]            if expired:                logger.info(f"🧹 清理过期语音消息: {len(expired)}条")        except Exception as e:            logger.error(f"❌ 清理语音消息失败: {e}")async def start_server():    """启动服务器"""    # 检查必要文件    required_files = [        (HTML_FILE, "HTML文件"),        (CSS_FILE, "CSS样式文件"),        (JS_FILE, "JavaScript文件")    ]    missing_files = []    for file, name in required_files:        if not os.path.exists(file):            missing_files.append(f"{file} ({name})")    if missing_files:        logger.error("❌ 缺少必要的文件:")        for file in missing_files:            logger.error(f"  - {file}")        return    # 生成SSL证书    ssl_context = get_ssl_context()    if not ssl_context:        logger.error("❌ SSL证书生成失败，无法启动HTTPS服务器")        return    # 创建应用    app = web.Application(client_max_size=10 * 1024 * 1024)    # 配置CORS    cors = aiohttp_cors.setup(app, defaults={        "*": aiohttp_cors.ResourceOptions(            allow_credentials=True,            expose_headers="*",            allow_headers="*",        )    })    # 添加路由    app.router.add_get('/', index)    app.router.add_get('/style.css', style_css)    app.router.add_get('/script.js', app_js)    app.router.add_get('/ws', ws_handler)    # 添加CORS    for route in list(app.router.routes()):        cors.add(route)    # 启动后台任务    asyncio.create_task(send_system_stats())    asyncio.create_task(cleanup_clients())    asyncio.create_task(cleanup_voice_messages())    # 启动服务器    runner = web.AppRunner(app)    await runner.setup()    # 获取本地IP    local_ip = get_local_ip()    # 启动HTTPS服务器    try:        site = web.TCPSite(runner, '0.0.0.0', 8000, ssl_context=ssl_context)        await site.start()        logger.info("=" * 60)        logger.info("✅ 摄像头共享服务器启动成功!")        logger.info("=" * 60)        logger.info("🎤 新增功能: 语音消息")        logger.info("✨ 功能特性:")        logger.info("    • 按住说话，松开发送")        logger.info("    • 支持最长30秒录音")        logger.info("    • 实时语音消息广播")        logger.info("    • 语音波形显示")        logger.info("    • 播放控制")        logger.info("    • 消息列表管理")        logger.info("=" * 60)        logger.info("🌐 访问地址:")        logger.info(f"    https://{local_ip}:8000")        logger.info(f"    https://localhost:8000")        logger.info("=" * 60)        # 保持运行        await asyncio.Future()    except OSError as e:        if e.errno == 98:            logger.error(f"❌ 端口8000被占用")        else:            logger.error(f"❌ 启动服务器失败: {e}")    except Exception as e:        logger.error(f"❌ 启动服务器失败: {e}")    finally:        await runner.cleanup()if __name__ == "__main__":    print("🎥 摄像头共享服务器 v2.0")    print("=" * 60)    # 检查依赖    try:        import aiohttp        import aiohttp_cors    except ImportError as e:        print("❌ 缺少依赖包!")        print("请安装: pip install aiohttp aiohttp-cors")        exit(1)    # 启动服务器    try:        asyncio.run(start_server())    except KeyboardInterrupt:        logger.info("服务器已停止")    except Exception as e:        logger.error(f"服务器启动失败: {e}")